frappe.ui.form.on('Lead', {
    refresh(frm) {
        if (frm.doc.creation) {
            const created_on = frappe.datetime.str_to_user(frm.doc.creation);
            const label = frappe._("Created On");
            frm.set_intro(`${label}: ${created_on}`);
        }
    }
})

frappe.ui.form.on('Batch', {
  refresh(frm) {
    const expiry_field = 'expiry_date';
    const posting_field = 'custom_batch_posting_date';
    const html_fieldname = 'custom_buttons';

    // 1) Luôn hiện expiry_date
    frm.toggle_display(expiry_field, true);

    // 2) Nếu posting date rỗng -> expiry_date = null
    if (!frm.doc[posting_field] && frm.doc[expiry_field]) {
      frm.set_value(expiry_field, null);
    }

    // 3) Render buttons
    const html = frm.fields_dict[html_fieldname];
    if (!html || !html.$wrapper) return;

    html.$wrapper.html(`
      <div class="d-flex flex-wrap" style="gap: 8px;">
        <button class="btn btn-default btn-sm" type="button" data-add="3">3 months</button>
        <button class="btn btn-default btn-sm" type="button" data-add="6">6 months</button>
        <button class="btn btn-default btn-sm" type="button" data-add="9">9 months</button>
        <button class="btn btn-default btn-sm" type="button" data-add="12">12 months</button>
        <button class="btn btn-default btn-sm" type="button" data-add="24">24 months</button>
      </div>
    `);

    html.$wrapper
      .off('click.add_months')
      .on('click.add_months', 'button[data-add]', (e) => {
        const months = Number(e.currentTarget.dataset.add);
        const base = frm.doc[posting_field];

        if (!base) {
          frappe.msgprint('Please set Batch Posting Date first.');
          return;
        }

        const d = frappe.datetime.str_to_obj(base); // 'YYYY-MM-DD'
        const new_date = frappe.datetime.obj_to_str(
          frappe.datetime.add_months(d, months)
        );

        frm.set_value(expiry_field, new_date);
      });
  },

  // Nếu posting date bị xoá -> expiry_date về null ngay
  custom_batch_posting_date(frm) {
    const expiry_field = 'expiry_date';
    const posting_field = 'custom_batch_posting_date';

    frm.toggle_display(expiry_field, true);

    if (!frm.doc[posting_field] && frm.doc[expiry_field]) {
      frm.set_value(expiry_field, null);
    }
  }
});

frappe.ui.form.on('Purchase Receipt', {
  onload(frm) {
    cache_posting_date_for_batch(frm);
  },
  refresh(frm) {
    cache_posting_date_for_batch(frm);
  },
  posting_date(frm) {
    cache_posting_date_for_batch(frm);
  }
});

function cache_posting_date_for_batch(frm) {
  // Lưu vào biến global trong cùng tab để Batch đọc được khi mở "Create New Batch"
  frappe.flags.batch_posting_date = frm.doc.posting_date || null;
    console.log(frappe.flags.batch_posting_date);
  // optional: lưu source để debug/truy vết
  frappe.flags.batch_source_doctype = frm.doc.doctype; // "Purchase Receipt"
  frappe.flags.batch_source_name = frm.doc.name || null;
}

